1589	void CommandProcessor::servicePsramPlay() {
1590	  if (frame_rate_hz_ <= 0 || psram_play_count_ <= 1) return;  // static index
1591	  uint32_t period_us = microseconds_per_second / (uint32_t)frame_rate_hz_;
1592	  uint32_t now = micros();
1593	  if ((now - last_advance_us_) < period_us) return;
1594	
1595	  uint16_t steps = 0;
1596	  while ((now - last_advance_us_) >= period_us) {
1597	    last_advance_us_ += period_us;
1598	    if (++steps >= psram_play_count_) { steps = psram_play_count_; break; }
1599	  }
1600	  psram_play_offset_ =
1601	      (uint16_t)((psram_play_offset_ + steps) % psram_play_count_);
1602	  buildPsramFrame((uint16_t)(psram_start_index_ + psram_play_offset_));
1603	}
