1687	bool CommandProcessor::ainCalValidate(AinCalChannel &c) const {
1688	  // Both points sampled (raw_open is never 0 on a live board: the pull-up sits
1689	  // at +10 V) and the span is real. An un-reworked board (LAB-209) saturates
1690	  // near full scale for BOTH points → span ≈ 0 → stays invalid, by design.
1691	  return c.raw_open > c.raw_gnd &&
1692	         (uint16_t)(c.raw_open - c.raw_gnd) >= ai_cal_min_span_counts;
1693	}
