 19	void CommandProcessor::begin() {
 20	  Wire.begin();
 21	  Wire.setClock(400000);
 22	
 23	  // Analog inputs (F1, analog-input-plan § 3): 12-bit conversions with 16x
 24	  // hardware averaging on both ADCs. Must precede any analogRead().
 25	  analogReadResolution(adc_resolution_bits);
 26	  analogReadAveraging(adc_averaging);
 27	  // Per-board calibration record (F2) from EEPROM; defaults when absent/stale.
 28	  ainCalLoad();
 29	
 30	  // Digital IO boot roles (#135). Port 1 ("Digital IO 1 (5V)", J3): a driven-
 31	  // LOW programmable output, as this firmware has always booted. Port 2
 32	  // ("Digital IO 2 (5V)", J4): in_trigger — U3 in B→A so the BNC feeds the
 33	  // panels' EINT net through the J30 shunt (external trigger for the
 34	  // triggered/gated panel display modes). This REPLACES the old pair of
 35	  // main.cpp setupExternalTriggerInput() + unconditional output init here,
 36	  // which together left D35 driving the EINT net against U3 (boot contention)
 37	  // — applyDioRole tri-states the data pin before flipping direction.
 38	  // Teensy pin 33 (R25→EINT) stays at its power-on INPUT default so nothing
 39	  // else drives the EINT net.
 40	  applyDioRole(1, DioRole::kOutProgrammable);
 41	  applyDioRole(2, DioRole::kInTrigger);
 42	}
 43	
 44	// Apply a DIO role with contention-safe pin-transition ordering. The
 45	// SN74LVC1T45 translator drives its A side (our data pin's net) whenever
 46	// DIR=LOW, so: to an output role, flip DIR HIGH FIRST (translator releases the
 47	// A net; the BNC floats for ~µs) and only then drive the data pin; to an
 48	// input/off role, tri-state the data pin FIRST and only then flip DIR LOW.
 49	// Note for rigs with the J30 shunt installed: port 2's A net feeds the panels'
 50	// EINT fanout through R216 regardless of role — an out_programmable port 2
 51	// pulses the panel trigger net whenever it toggles (hardware property, not
 52	// firmware-preventable).
 53	void CommandProcessor::applyDioRole(uint8_t port, DioRole role) {
 54	  const uint8_t data = (port == 1) ? do1_data_pin : do2_data_pin;
 55	  const uint8_t dir  = (port == 1) ? do1_dir_pin  : do2_dir_pin;
 56	  pinMode(dir, OUTPUT);
 57	  if (role == DioRole::kOutProgrammable || role == DioRole::kOutFramescan) {
 58	    digitalWrite(dir, HIGH);   // translator A side becomes an input (stops driving)
 59	    pinMode(data, OUTPUT);
 60	    digitalWrite(data, LOW);   // defined level before anything observes the BNC
 61	  } else {
 62	    pinMode(data, INPUT);      // we stop driving FIRST
 63	    digitalWrite(dir, LOW);    // then the translator turns around (BNC → A net)
 64	  }
 65	  dio_role_[port - 1] = role;
 66	  // Keep the SpiManager frame-scan gate in sync (one slot per port).
 67	  spi_.setFramescanGatePins(
 68	      dio_role_[0] == DioRole::kOutFramescan ? (int16_t)do1_data_pin : (int16_t)-1,
 69	      dio_role_[1] == DioRole::kOutFramescan ? (int16_t)do2_data_pin : (int16_t)-1);
 70	  DBG_PRINTF("[cmd] dio role port=%u -> %s\n", (unsigned)port, dioRoleName(role));
 71	}
 72	
 73	const char *CommandProcessor::dioRoleName(DioRole role) const {
 74	  switch (role) {
 75	    case DioRole::kOff:             return "off";
 76	    case DioRole::kInTrigger:       return "in_trigger";
 77	    case DioRole::kOutProgrammable: return "out_programmable";
 78	    case DioRole::kOutFramescan:    return "out_debug_framescan";
 79	  }
 80	  return "?";
 81	}
