 87	void CommandProcessor::processCommand() {
 88	  // Drain one command from each source per loop iteration. Net first
 89	  // (lower-latency TCP path), then serial. Each source uses its own
 90	  // response buffer; current_source_ tells the handlers which one to
 91	  // send the reply back through.
 92	  //
 93	  // A source with an active 0x84 download (dl_active_, issue #16 fix 2),
 94	  // 0x85 upload (ul_active_), or 0x8A archive (ar_active_, PR #27 review
 95	  // point 2) is skipped here even if it has a newly-parsed command waiting.
 96	  //
 97	  // Downloads and archives: sendRaw() flushes any queued response frame
 98	  // before writing raw bytes, so handling a new command on that same source
 99	  // would splice a framed response into the middle of the in-flight raw
100	  // byte stream, corrupting it from the client's point of view.
101	  //
102	  // Uploads: a command that hands off to serviceUpload() is deliberately
103	  // left un-consumed (hasCommand() stays true) so parseIncoming() doesn't
104	  // mistake its still-arriving raw file bytes for a new framed command.
105	  // handleBulkWriteCommand()'s return value says whether THIS call handed
106	  // off (true) or was fully, synchronously handled already (false). See
107	  // the ul_* fields' comment in CommandProcessor.h (PR #27 review point 1)
108	  // for why consuming based on the stale global ul_active_ flag instead let
109	  // a REJECTED command get redispatched, and re-rejected, on every loop()
110	  // iteration for as long as an UNRELATED transfer on the other source ran.
111	  //
112	  // Either way, the command stays queued until the transfer finishes. The
113	  // OTHER source is unaffected — that's the concurrency fix 2 is for.
114	  if (net_.hasCommand() && !(dl_active_ && dl_source_ == &net_)
115	                        && !(ul_active_ && ul_source_ == &net_)
116	                        && !(ar_active_ && ar_source_ == &net_)) {
117	    current_source_ = &net_;
118	    const ParsedCommand &cmd = net_.command();
119	    if (cmd.is_bulk) {
120	      bool async_handoff = handleBulkWriteCommand(cmd);
121	      if (!async_handoff) net_.commandConsumed();
122	    } else if (cmd.is_stream) {
