124	      net_.commandConsumed();
125	    } else {
126	      handleBinaryCommand(cmd);
127	      net_.commandConsumed();
128	    }
129	  }
130	  if (serial_.hasCommand() && !(dl_active_ && dl_source_ == &serial_)
131	                           && !(ul_active_ && ul_source_ == &serial_)
132	                           && !(ar_active_ && ar_source_ == &serial_)) {
133	    current_source_ = &serial_;
134	    const ParsedCommand &cmd = serial_.command();
135	    if (cmd.is_bulk) {
136	      bool async_handoff = handleBulkWriteCommand(cmd);
137	      if (!async_handoff) serial_.commandConsumed();
138	    } else if (cmd.is_stream) {
