1779	bool CommandProcessor::loadFrame(uint16_t frame_index) {
1780	  uint8_t err = sd_.readFrame(frame_index, frame_buf_, sizeof(frame_buf_));
1781	  if (err != CE_NONE) {
1782	    DBG_PRINTF("[cmd] loadFrame %u failed err=%u\n",
1783	               (unsigned)frame_index, (unsigned)err);
1784	    showError(err);
1785	    return false;
1786	  }
1787	  frame_byte_count_ = (uint16_t)(stream_frame_prefix_byte_count
1788	                                 + (uint32_t)sd_.info().num_panels * block_byte_count_);
1789	  patchDispMode();
1790	  patchTrialDuty();
1791	  if (ao_mode_ == 1) {
1792	    // frame_number AO (#135): DAC tracks the frame position, 0 V = frame 0 ..
1793	    // 5 V = last frame. loadFrame only runs when the index CHANGES, so the
1794	    // ~100 µs blocking I2C write costs nothing while a frame is held.
1795	    writeDacMv(frame_count_ > 1
1796	                   ? (uint16_t)((uint32_t)frame_index * 5000 / (frame_count_ - 1))
1797	                   : (uint16_t)0);
1798	  } else if (ao_lut_len_ > 0 && ao_lut_mode_ == 0) {
1799	    ao_lut_idx_ = (uint16_t)(frame_index % ao_lut_len_);
1800	    applyAoLut(ao_lut_idx_);
1801	  }
1802	  return true;
1803	}
