1809	void CommandProcessor::enterAllOff() {
1810	  spi_.disarmRefreshTimer();
1811	  // Panels run in Persistent mode and HOLD their last received frame, so simply
1812	  // stopping transmission leaves them lit. Push an all-dark frame so they
1813	  // actually blank, then go quiet. Sent a few times for reliability on the
1814	  // shared (wired-OR CIPO) bus; one dropped frame would otherwise stay lit.
1815	  fillFrameBufferDark();
1816	  for (uint8_t i = 0; i < 3; ++i) {
1817	    spi_.transferFrame(frame_buf_, block_byte_count_);
1818	  }
1819	  state_ = ArenaState::ALL_OFF;
1820	  frame_byte_count_ = 0;
1821	  trial_duty_ = 0;  // trial over — per-trial duty does not outlive it (#33)
1822	}
