149	void CommandProcessor::handleBinaryCommand(const ParsedCommand &cmd) {
150	  const uint8_t *buf = cmd.data;
151	  uint8_t claimed_len = buf[0];
152	  if (cmd.data_len - 1 != claimed_len) {
153	    // Malformed framing — drop silently to keep the wire quiet.
154	    return;
155	  }
156	
157	  uint8_t pos = 1;
158	  uint8_t command_byte = buf[pos++];
159	  DBG_PRINTF("[cmd] handleBinary cmd=0x%02X len=%u\n",
160	             command_byte, (unsigned)cmd.data_len);
161	
162	  switch (command_byte) {
163	    case ALL_OFF_CMD:
164	      enterAllOff();
165	      current_source_->sendResponse(command_byte, 0, "All-Off Received");
166	      break;
167	
168	    case ALL_ON_CMD:
169	      // PR #27 review point 8: a state transition mid-transfer doesn't
170	      // disrupt the transfer itself (serviceDownload()/serviceUpload()/
171	      // serviceArchive() don't read state_ at all) or corrupt anything (SD
172	      // is SDIO, not shared with the panel SPI path, and loop() is
173	      // single-threaded so accesses are naturally serialized), but it's
174	      // still confusing at the bench to have the arena visibly change while
175	      // an SD transfer nobody can see is still in flight, so refuse it.

220	      continue;
