222	    size_t want = ((size_t)room < (len - off)) ? (size_t)room : (len - off);
223	    size_t n = client_.write(buf + off, want);
224	    if (n > 0) {
225	      off += n;
226	      stall_deadline = millis() + kStallTimeoutMs;
227	    } else {
228	      if ((int32_t)(millis() - stall_deadline) >= 0) break;
229	      delayMicroseconds(250);
230	    }
231	  }
232	  return off;
