23	// Sentinel-prefixes every line so this shares the same demux convention as
24	// DBG_PRINTF (constants.h) instead of injecting bare ASCII into the USB-CDC
25	// binary-response channel. Can't gate on g_dbg_on like DBG_PRINTF does --
26	// a host can only set that AFTER boot, and this needs to fire during boot
27	// itself -- so unlike DBG_PRINTF it prints unconditionally whenever
28	// DEBUG_SERIAL is compiled in. It still never blocks the boot sequence:
29	// no Serial.flush(), and each byte checks availableForWrite() first and
30	// silently drops instead of waiting on a full/absent host.
31	class SentinelPrint : public Print {
32	 public:
33	  size_t write(uint8_t c) override {
34	    if (Serial.availableForWrite() < (at_line_start_ ? 2 : 1)) return 0;
35	    if (at_line_start_) {
36	      Serial.write(AC::constants::diag_line_sentinel);
37	      at_line_start_ = false;
38	    }
39	    Serial.write(c);
40	    if (c == '\n') at_line_start_ = true;
41	    return 1;
42	  }
43	  size_t write(const uint8_t *buffer, size_t size) override {
44	    size_t n = 0;
45	    for (size_t i = 0; i < size; ++i) n += write(buffer[i]);
46	    return n;
47	  }
48	
49	 private:
50	  bool at_line_start_ = true;
51	};
52	#endif
