103	// The external-trigger input path (BNC "Digital IO 2 (5V)"/J4 -> U3 SN74LVC1T45
104	// -> J30 shunt -> R216 -> TNY.EINT fanout -> all panels' EINT/GP45) is now set
105	// up by CommandProcessor::begin() as DIO role `in_trigger` on port 2
106	// (SET_DIO_ROLE 0xAC, #135) — the old setupExternalTriggerInput() here flipped
107	// U3.DIR after begin() had made D35 an output, leaving D35 driving the EINT
108	// net against U3 (boot contention). applyDioRole tri-states D35 first.
109	
110	void loop() {
111	  // Must run BEFORE net.serviceTcp(): net_'s client_ is a single reused slot,
112	  // so if the client owning an active 0x84/0x85/0x8A transfer disconnected,
113	  // serviceTcp() below would silently swap in a brand-new client on the same
114	  // slot and start parsing/streaming its bytes before this ever got a chance
115	  // to see the OLD (dead) connection state (PR #27 review point 5).
116	  cmdProc.serviceDisconnects();
117	  // net.serviceTcp();           // 1a. Accept TCP client, read and parse commands
118	  serial.serviceUsb();        // 1b. Read and parse commands from USB CDC
119	  cmdProc.processCommand();   // 2.  Handle one parsed command per source
120	  cmdProc.serviceDisplay();   // 3.  Re-transmit current frame at refresh rate
121	  cmdProc.serviceDownload();  // 3b. Stream one 0x84 download chunk, if one is in flight
122	  cmdProc.serviceUpload();    // 3c. Stream one 0x85 upload chunk, if one is in flight
123	  cmdProc.serviceArchive();   // 3d. Stream one 0x8A archive step, if one is in flight
124	  // net.flushResponses();       // 4a. Send queued responses over TCP
125	  serial.flushResponses();    // 4b. Send queued responses over USB CDC
126	
127	#ifdef DEBUG_SERIAL
128	  if (!ipPrinted && Serial && net.ipAddress()[0] != '\0') {
129	    DBG_PRINTF("MAC: %s  IP: %s\n", net.macAddress(), net.ipAddress());
130	    ipPrinted = true;
131	  }
132	#endif
133	}
