135	void blinkStartupPattern() {
136	  static constexpr uint8_t  LED_PIN  = LED_BUILTIN;
137	  static constexpr uint32_t SHORT_MS = 100;
138	  static constexpr uint32_t LONG_MS  = 300;
139	  static constexpr uint32_t PAUSE_MS = 100;
140	  static constexpr uint32_t GROUP_PAUSE_MS = 300;
141	
142	  pinMode(LED_PIN, OUTPUT);
143	
144	  // Morse "OK": O = long long long, K = long short long.
145	  const uint32_t pattern[][3] = {
146	      { LONG_MS, LONG_MS,  LONG_MS },
147	      { LONG_MS, SHORT_MS, LONG_MS },
148	  };
149	
150	  for (size_t g = 0; g < sizeof(pattern) / sizeof(pattern[0]); ++g) {
151	    if (g > 0) delay(GROUP_PAUSE_MS);
152	    for (size_t i = 0; i < sizeof(pattern[0]) / sizeof(pattern[0][0]); ++i) {
153	      digitalWriteFast(LED_PIN, HIGH);
154	      delay(pattern[g][i]);
155	      digitalWriteFast(LED_PIN, LOW);
156	      delay(PAUSE_MS);
157	    }
158	  }
159	}
